.input-btn-ai      { left: var(--ai-x) !important;      top: var(--ai-y) !important; }
.send-btn-custom   { left: var(--send-x) !important;    top: var(--send-y) !important; }
.input-btn-mic     { left: var(--mic-x) !important;     top: var(--mic-y) !important; }
.input-btn-sticker { left: var(--sticker-x) !important; top: var(--sticker-y) !important; }

/* ② AI 键 → 信封+右箭头 */
