  --input-box-placeholder: #bdbdbd;
  --input-caret-color: #bdbdbd;

  --ph-left: 30px;        /* 占位文案 + 输入文字的起点,越大越靠右 */
  --input-h: 20px;        /* 输入区固定高度,写满后出滑动条 */
}
/* ① 底栏白底 */
.chat-detail-screen .input-area-custom {
  background: #ffffff !important;
  background-image: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
/* ③ 占位文案:右移,字号和输入文字一致 */
