:root {
  --sg-gray-050: rgba(248,249,250,.96);
  --sg-gray-100: rgba(242,244,245,.94);
  --sg-gray-150: rgba(234,237,239,.92);
  --sg-gray-200: rgba(226,230,233,.92);
  --sg-gray-300: rgba(205,211,216,.92);
  --sg-gray-ink: #464d53;
  --sg-gray-muted: #8e979e;

  --sg-glass:
    rgba(255,255,255,.70);

  --sg-border:
    rgba(255,255,255,.84);

  --sg-text:
    #30353a;

  --sg-muted:
    #8f989f;

  --sg-faint:
    #b9c0c5;

  --sg-shadow:
    0 5px 16px rgba(45,50,55,.028),
    0 1px 2px rgba(45,50,55,.014);

  --sg-card-shadow:
    0 8px 22px rgba(45,50,55,.034),
    0 1px 3px rgba(45,50,55,.016);

  --sg-input-glass:
    rgba(239,242,244,.78);

  --sg-input-border:
    rgba(215,220,224,.88);

  --sg-input-shadow:
    0 7px 19px rgba(45,50,55,.030),
    inset 0 1px 0 rgba(255,255,255,.66);

  --sg-input-text:
    #495158;

  --sg-input-placeholder:
    #9ca4aa;

  --sg-send-bg:
    rgba(236,239,241,.88);

  --sg-send-border:
    rgba(210,215,219,.92);

  --sg-send-color:
    #69747c;
}

