  --ph-l: 13px;                           /* 占位文案区域：离输入栏左边 */
  --ph-r: 69px;                           /* 占位文案区域：离输入栏右边（表情键+AI 键的宽度） */

  --send-icon-size: 22px;                 /* 发送键图标大小 */
  --stop-btn-color: #c4c4c4;
  --stop-btn-bg: transparent;

  /* App 自带变量 */
  --input-area-bg: #ffffff;
  --input-area-bg-image: none;
  --input-area-blur: 0px;
  --input-box-font-size: 13px;
  --input-box-color: #bdbdbd;
  --input-box-placeholder: #bdbdbd;
  --input-caret-color: #bdbdbd;
}

